package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import java.io.StringWriter;
import java.io.Writer;
import java.io.IOException;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Lang_17_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        CharSequenceTranslator translator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, Writer out) throws IOException {
                // Simple translator that just writes the input character as is
                out.write(Character.toChars(Character.codePointAt(input, index)));
                return 1;
            }
        };

        // Input with surrogate pairs and a character that requires special handling
        String input = "A\uD835\uDD0A\uD835\uDD1E"; // 'A' followed by two surrogate pairs
        StringWriter writer = new StringWriter();
        try {
            translator.translate(input, writer);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        // Expecting the output to be the same as input
        assertEquals("A\uD835\uDD0A\uD835\uDD1E", writer.toString());
    }
}

